&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;회사 소개&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;쿠팡은&amp;nbsp;고객 감동 실현을 위해 존재합니다&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;.&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;고객들이&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;&quot;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;쿠팡&amp;nbsp;없이 그동안 어떻게 살았을까&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;?&quot;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;라고 말할 때&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;,&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;비로소 우리의 미션을 실현하고 있음을 알 수 있습니다&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;.&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;고객들의 쇼핑과 식사&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;,&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;생활 전반을 편하게 만들겠다는 유일한 집념으로&amp;nbsp;쿠팡은&amp;nbsp;수억 달러 규모의&amp;nbsp;이커머스&amp;nbsp;산업 전반의 혁신을 이끌고 있습니다&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;.&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;쿠팡은&amp;nbsp;가장 빠르게 성장하는&amp;nbsp;이커머스&amp;nbsp;기업 중 하나로&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;,&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;국내 커머스 업계에서의 독보적인 입지와&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;,&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;고객 신뢰를 구축했습니다&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;.&lt;/span&gt; &lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;쿠팡은&amp;nbsp;스타트업 문화를 기반으로 한 글로벌 대형 상장사라고 자부합니다&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;.&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;이것이 창립 당시의 기민함을 지하며&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;,&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;신규 서비스를 끊임없이 출시하며 비즈니스를 확장해 나가는 우리의 성장 동력입니다&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;.&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;쿠팡의&amp;nbsp;모든 임직원에게는 기업가 정신을 갖추고 새로운 혁신과 이니셔티브를 추진할 수 있는 기회가 주어집니다&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;.&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;주저 없이 일에 뛰어들어 성과를 이루고자 하는 과감성이&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;,&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;바로&amp;nbsp;쿠팡이&amp;nbsp;일하는 방식의 본질입니다&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;.&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;쿠팡에서는&amp;nbsp;여러분&amp;nbsp;자신&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;,&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;동료&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;,&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;팀 그리고 회사 전체가 매일 성장하는 모습을 목격할 것입니다&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;.&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559685&amp;quot;:120,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259,&amp;quot;335559991&amp;quot;:120}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;쿠팡의&amp;nbsp;모든 직원은 커머스의 미래를 만들겠다는&amp;nbsp;쿠팡의&amp;nbsp;미션에 진심입니다&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;.&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;우리는 고객의 문제를 해결해 나가고&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;,&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;전통적인 관념과 통념에 맞서며 실현 가능한 한계를 뛰어넘고 있습니다&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;.&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;고가용성&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;(always-on)&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;과 최첨단의 앞선 기술&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;(high-tech),&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;초연결사회&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;(hyper-connected world)&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;에서의 놀라운 업무 경험을 원하신다면&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;,&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;지금 바로&amp;nbsp;쿠팡에&amp;nbsp;합류하세요&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span lang=&quot;en-US&quot;&gt;직무 설명&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span lang=&quot;en-US&quot;&gt;쿠팡의 핀테크 사업은 소비자와 판매자 모두가 확장된 금융 서비스 솔루션을 누릴 수 있도록 새로운 방식을 선보이고 있습니다. &lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span lang=&quot;en-US&quot;&gt;쿠팡페이는&amp;nbsp;&lt;/span&gt;Coupang.com &lt;span lang=&quot;en-US&quot;&gt;및 쿠팡이츠에서 상품을 구매하는 고객부터 쿠팡의 오픈마켓을 이용하는 판매자 그리고 쿠팡이츠 가맹점까지 쿠팡을 이용하는 모든 이들에게 혁신적인 결제 및 금융 서비스 솔루션을 제공하는 데 중점을 두고 있습니다. &lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span lang=&quot;en-US&quot;&gt;금융과 기술을 결합한 핀테크 분야 내에서 광범위한 경험을 쌓으며 업무하시길 원한다면, 쿠팡 페이와 함께 하세요. 우리는 고객이 계산하는 시간을 줄여서 고객이 좋아하는 것을 쇼핑하는 데 더 많은 시간을 보낼 수 있도록 돕습니다.&lt;/span&gt;&lt;/p&gt;
&lt;div&gt;쿠팡페이의 Director, External Relations는 빠르게 확장되는 핀테크 비즈니스 환경에서 규제기관, 금융 파트너사, 산업 전반의 다양한 이해관계자와 전략적 관계를 구축하고 이를 지속적으로 관리하는 리더십 포지션입니다.&lt;br&gt;&lt;br&gt;이 역할은 단순한 대외 커뮤니케이션을 넘어, 신사업 추진 과정에서 필요한 규제 환경을 선제적으로 조성하고, 결제 및 금융 생태계 내 핵심 파트너들과의 전략적 협력 구조를 설계하며, 동시에 리스크·정책·운영 조직과의 긴밀한 협업을 통해 실제 사업 실행력을 확보하는 데 핵심적인 기여를 합니다. 이러한 총합적인 역할을 통해 쿠팡페이의 지속 가능한 성장을 외부 환경 측면에서 견인합니다.&lt;/div&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;업무 내용&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;div&gt;규제기관(금융위, 금감원 등)과의 전략적 관계 구축 및 커뮤니케이션 총괄&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;div&gt;카드사, PG/VAN, 은행 등 주요 파트너사와의 협력 구조 설계 및 관리&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;div&gt;전자금융 및 결제 규제 변화에 대한 대응 전략 수립 및 실행&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;div&gt;신사업 추진 시 규제 리스크 사전 식별 및 외부 협의 리딩&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;div&gt;산업 협의체 및 정책 아젠다 참여를 통한 대외 영향력 강화&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;div&gt;내부 조직(Risk, Legal, Biz 등)과의 협업을 통한 대외 이슈 대응 및 정렬&lt;/div&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;자격&lt;/span&gt;&lt;/strong&gt;&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;요건&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;div&gt;핀테크, 금융, 결제, 또는 규제기관 관련 분야에서 12년 이상의 경력을 보유하신 분&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;div&gt;금융당국, 카드사, PG 등과의 대외 협력 및 규제 대응 경험이 있으신 분&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;div&gt;전자금융 및 결제 산업 구조에 대한 깊은 이해를 갖추신 분&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;div&gt;신사업 또는 신규 서비스 환경에서 외부 이해관계자 조율 및 실행 경험이 있으신 분&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;div&gt;복잡한 규제 및 비즈니스 환경에서 의사결정을 리드할 수 있는 전략적 사고 및 커뮤니케이션 역량을 보유하신 분&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;div&gt;5년 이상의 조직 리딩 경험이 있으신 분&lt;/div&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;우대사항&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;div&gt;금융감독원, 금융위원회 등 규제기관 근무 경험이 있으신 분&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;div&gt;카드사, PG/VAN, 간편결제 등 핵심 플레이어 네트워크를 보유하신 분&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;div&gt;리스크/컴플라이언스/법무 등과의 협업 경험 또는 관련 이해도가 있으신 분&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;div&gt;하이그로스 조직 또는 신사업 환경에서 정책 및 대외 전략 수립 경험이 있으신 분&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;div&gt;글로벌 이해관계자 대응이 가능한 수준의 영어 커뮤니케이션 역량을 보유하신 분&lt;/div&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;전형 절차 및&lt;/strong&gt;&lt;strong&gt; &lt;/strong&gt;&lt;strong&gt;안내&lt;/strong&gt;&lt;strong&gt; &lt;/strong&gt;&lt;strong&gt;사항&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;br&gt;전형&lt;/strong&gt;&lt;strong&gt; &lt;/strong&gt;&lt;strong&gt;절차&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;서류전형 - 1차 화상면접 - 2차 화상면접 – 최종 합격&lt;/li&gt;
&lt;li&gt;전형절차는 직무별로 다르게 운영될 수 있으며, 일정 및 상황에 따라 변동 될 수 있습니다.&lt;/li&gt;
&lt;li&gt;전형 일정 및 결과는 지원서에 등록하신 이메일로 개별 안내 드립니다.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;br&gt;참고&lt;/strong&gt;&lt;strong&gt; &lt;/strong&gt;&lt;strong&gt;사항&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;고용형태는 정규직으로 수습기간 12주를 포함합니다. 단, 업무상 필요한 경우에는 상기 수습기간을 적용하지 않거나 단축 또는 연장할 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;본 공고는 모집 완료 시 조기 마감될 수 있습니다.&lt;/li&gt;
&lt;li&gt;지원서 내용 중 허위사실이 있는 경우에는 합격이 취소될 수 있습니다.&lt;/li&gt;
&lt;li&gt;취업 보호 대상자(보훈대상자, 장애인 등)는 관련 법률에 따라 채용우대를 받을 수 있습니다.&lt;/li&gt;
&lt;li&gt;직급과 담당 업무 범위는 후보자의 전반적인 경력과 경험 등 제반사정을 고려하여 변경될 수 있습니다. 이러한 변경이 필요할 경우, 최종 합격 통지 전 적절한 시기에 후보자와 커뮤니케이션 될 예정입니다.&lt;/li&gt;
&lt;li&gt;채용 및 업무 수행과 관련하여 요구되는 법령상 자격이 갖추어지지 않은 경우 채용이 제한될 수 있습니다.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;개인정보 처리방침&lt;/strong&gt; &lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;쿠팡 그룹은 입사지원자 개인정보 처리방침(아래 링크)에 따라 귀하의 개인정보를 수집하여 처리합니다. &lt;a href=&quot;https://www.coupang.jobs/kr/privacy-policy/&quot;&gt;https://www.coupang.jobs/kr/privacy-policy/&lt;/a&gt; &amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;서류&lt;/strong&gt;&lt;strong&gt; &lt;/strong&gt;&lt;strong&gt;반환 정책&lt;/strong&gt; &lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;ol&gt;
&lt;li data-leveltext=&quot;-&quot; data-font=&quot;맑은 고딕&quot; data-listid=&quot;39&quot; data-list-defn-props=&quot;{&amp;quot;335551671&amp;quot;:0,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;맑은 고딕&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;-&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;0&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;본 고지는 『채용절차의공정화에관한법률』제11조제6항에 따른 것 입니다.&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;-&quot; data-font=&quot;맑은 고딕&quot; data-listid=&quot;39&quot; data-list-defn-props=&quot;{&amp;quot;335551671&amp;quot;:0,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;맑은 고딕&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;-&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;0&quot; data-aria-level=&quot;1&quot;&gt;당사 채용에 응시한 구직자 중 최종 합격이 되지 못한 구직자는 『채용절차의 공정화에 관한 법률』에 따라 제출한 채용서류의 반환을 청구할 수 있음을 알려 드립니다. 다만, 홈페이지 또는 전자우편으로 제출된 경우나 구직자가 당사의 요구 없이 자발적으로 제출한 경우에는 그러하지 아니하며, 천재지변이나 그 밖에 당사에게 책임 없는 사유로 채용서류가 멸실된 경우에는 반환한 것으로 봅니다.&lt;/li&gt;
&lt;li data-leveltext=&quot;-&quot; data-font=&quot;맑은 고딕&quot; data-listid=&quot;39&quot; data-list-defn-props=&quot;{&amp;quot;335551671&amp;quot;:0,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;맑은 고딕&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;-&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;0&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;eop&quot;&gt;위2항 본문에 따라 채용 서류 반환 청구를 하는 구직자는 채용 서류 반환 청구서 [채용절차의 공정화에 관한 법률 시행규칙 별지 제 3 호 서식]를 작성하여 이메일 (recruitingops@coupang.com) 로 제출하면, 제출이 확인된 날로부터 14 일 이내에 지정한 주소지로 등기우편을 통하여 발송해 드립니다. 이 경우 등기우편요금은 수신자 부담으로 하게 되오니 유념하시기 바랍니다. &lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;-&quot; data-font=&quot;맑은 고딕&quot; data-listid=&quot;39&quot; data-list-defn-props=&quot;{&amp;quot;335551671&amp;quot;:0,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;맑은 고딕&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;-&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;0&quot; data-aria-level=&quot;1&quot;&gt;당사는 위2항 본문에 따른 구직자의 반환 청구에 대비하여 채용 여부가 확정된 날로부터 180 일간 구직자가 제출한 채용서류 원본을 보관하게 되며, 그때까지 채용서류의 반환을 청구하지 아니할 경우에는 『개인정보 보호법』에 따라 지체 없이 채용서류 일체를 파기할 예정입니다.&lt;/li&gt;
&lt;li data-leveltext=&quot;-&quot; data-font=&quot;맑은 고딕&quot; data-listid=&quot;39&quot; data-list-defn-props=&quot;{&amp;quot;335551671&amp;quot;:0,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;맑은 고딕&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;-&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;0&quot; data-aria-level=&quot;1&quot;&gt;단, 위 1항 내지 4항의 내용은 대한민국의 노동 관계 법령이 적용되는 경우에만 적용됩니다. 그 이외의 경우에는 적용되지 않습니다.&lt;/li&gt;
&lt;/ol&gt;

alphapartners-coupang:greenhouse:7937231.descriptionHtml:
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++ &lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;(Please remove the guide section when posting the job) &lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
